@import "@fontsource-variable/mona-sans";
@import "@fontsource-variable/azeret-mono";

/* Light (faithful): a putty-tan page (#ccc8c3) with graphite text (#333), burnt orange
   (#cf6d46) for every accent, navy (#152536) for cards. Muted is a slightly deeper tan so
   photo placeholders read on the page. Square corners throughout. */
:root {
  --background: #ccc8c3;
  --foreground: #333333;
  --card: #152536;
  --card-foreground: #ffffff;
  --popover: #101c29;
  --popover-foreground: #ffffff;
  --primary: #cf6d46;
  --primary-foreground: #ffffff;
  --secondary: #bfbab4;
  --secondary-foreground: #333333;
  --muted: #b6b0a9;
  --muted-foreground: #4d4b48;
  --accent: #ffffff;
  --accent-foreground: #152536;
  --destructive: #b8412c;
  --destructive-foreground: #ffffff;
  --border: #9c9790;
  --input: #9c9790;
  --ring: #cf6d46;
  --highlight: #cf6d46;
  --highlight-foreground: #ffffff;
  --glow: #e08a63;
  --chart-1: #cf6d46;
  --chart-2: #152536;
  --chart-3: #6f7f8e;
  --chart-4: #a8784f;
  --chart-5: #4d4b48;
  --sidebar: #bfbab4;
  --sidebar-foreground: #333333;
  --sidebar-primary: #cf6d46;
  --sidebar-primary-foreground: #ffffff;
  --sidebar-accent: #b6b0a9;
  --sidebar-accent-foreground: #333333;
  --sidebar-border: #9c9790;
  --sidebar-ring: #cf6d46;

  --typeface-body: "Mona Sans Variable", "Helvetica Neue", Arial, sans-serif;
  --typeface-display: "Mona Sans Variable", "Helvetica Neue", Arial, sans-serif;
  --typeface-mono: "Azeret Mono Variable", ui-monospace, Menlo, Consolas, monospace;
  --radius: 0rem;
  --page-width: 90rem;
  /* 17px on phones, 35px at 1440 */
  --page-gutter: clamp(1.0625rem, 2.43vw, 2.1875rem);
  /* 60px on phones, 120px at 1440 */
  --section-y: clamp(3.75rem, 8.33vw, 7.5rem);
}

/* Dark (sibling, and the navy bands of the light page): the deeper navy of the cookie
   notice (#101c29) as the page, the footer navy (#152536) for cards, white text, the same
   orange. Muted is a lifted navy so photo placeholders read on it. */
.dark {
  --background: #101c29;
  --foreground: #ffffff;
  --card: #152536;
  --card-foreground: #ffffff;
  --popover: #101c29;
  --popover-foreground: #ffffff;
  --primary: #cf6d46;
  --primary-foreground: #ffffff;
  --secondary: #1d3147;
  --secondary-foreground: #ffffff;
  --muted: #2a3d52;
  --muted-foreground: rgb(255 255 255 / 0.7);
  --accent: #ffffff;
  --accent-foreground: #152536;
  --destructive: #e0664c;
  --destructive-foreground: #ffffff;
  --border: rgb(255 255 255 / 0.22);
  --input: rgb(255 255 255 / 0.22);
  --ring: #cf6d46;
  --highlight: #e08a63;
  --highlight-foreground: #101c29;
  --glow: #cf6d46;
  --chart-1: #cf6d46;
  --chart-2: #ccc8c3;
  --chart-3: #6f8aa4;
  --chart-4: #d9a27c;
  --chart-5: #8c97a3;
  --sidebar: #152536;
  --sidebar-foreground: #ffffff;
  --sidebar-primary: #cf6d46;
  --sidebar-primary-foreground: #ffffff;
  --sidebar-accent: #1d3147;
  --sidebar-accent-foreground: #ffffff;
  --sidebar-border: rgb(255 255 255 / 0.22);
  --sidebar-ring: #cf6d46;
}
